import {getPortfolioProjects} from './portfolio-data.mjs';
export function createProjectMap({esc,btn,crumb}){
 const points=[[26,43],[50,31],[74,42],[37,70],[68,72],[53,53]];
 const projects=()=>getPortfolioProjects().filter(p=>p.published);
 const image=p=>!p.cover?Object.values(p.stages||{}).flatMap(s=>s.photos||[])[0]?.src||'/assets/hero.webp':typeof p.cover==='string'?p.cover:p.cover?.src;
 const roadArt=`<svg class="pm-roads" viewBox="0 0 1000 700" aria-hidden="true"><defs><pattern id="pm-grid" width="100" height="80" patternUnits="userSpaceOnUse"><path d="M0 0H100V80" fill="none" stroke="#ccd7d3" stroke-width="2"/></pattern></defs><rect width="1000" height="700" fill="#e3eae4"/><path d="M-50 500C140 600 205 300 390 370S620 660 1100 300" fill="none" stroke="#b5ced4" stroke-width="48"/><path d="M-50 500C140 600 205 300 390 370S620 660 1100 300" fill="none" stroke="#c6dce0" stroke-width="37"/><rect width="1000" height="700" fill="url(#pm-grid)"/><g fill="#d3decf"><rect x="130" y="95" width="155" height="90" rx="30"/><rect x="735" y="450" width="125" height="150" rx="45"/><rect x="395" y="415" width="90" height="95" rx="20"/></g><g fill="none" stroke="#f9f9f0" stroke-width="15"><ellipse cx="500" cy="350" rx="335" ry="225"/><ellipse cx="500" cy="350" rx="180" ry="120"/><path d="M0 150L1000 550M150 0L850 700M1000 50L0 660M500 0V700M0 350H1000"/></g><g fill="none" stroke="#aebfba" stroke-width="1"><ellipse cx="500" cy="350" rx="335" ry="225"/><ellipse cx="500" cy="350" rx="180" ry="120"/><path d="M0 150L1000 550M150 0L850 700M1000 50L0 660M500 0V700M0 350H1000"/></g></svg>`;
 function scene(list,compact=false){return `<div class="pm-viewport ${compact?'pm-compact':''}" data-project-map><div class="pm-map-plane">${roadArt}${list.slice(0,6).map((p,i)=>`<button type="button" class="pm-pin ${i===0?'is-active':''}" style="--x:${points[i][0]}%;--y:${points[i][1]}%" data-map-project="${esc(p.id)}" aria-label="Показать: ${esc(p.title)}" aria-pressed="${i===0}"><span>${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div><div class="pm-popover" data-map-popover aria-live="polite">${list[0]?popCard(list[0]):''}</div><span class="pm-scale">Схематичная демонстрация · без реальных адресов</span><div class="pm-controls"><button type="button" data-map-zoom="in" aria-label="Приблизить">+</button><button type="button" data-map-zoom="out" aria-label="Отдалить">−</button><button type="button" data-map-zoom="reset" aria-label="Вернуть масштаб">↺</button></div></div>`;}
 function popCard(p){return `<a class="pm-object" href="#/portfolio/${esc(p.id)}"><span class="pm-object-image"><img src="${esc(image(p))}" alt="${esc(p.title)}" width="560" height="400" loading="lazy"></span><span class="pm-object-info"><small>${p.isDemo?'ДЕМОНСТРАЦИОННЫЙ ПРОЕКТ':'ПРОЕКТ'}</small><strong>${esc(p.title)}</strong><span>Посмотреть работу ↗</span></span></a>`;}
 function homepage(){const list=projects();return `<section class="section pm-home"><div class="section-top"><div><div class="eyebrow">ПРОЕКТЫ В ПРОСТРАНСТВЕ</div><h2>У каждой работы<br><em>своё место.</em></h2></div><p>Выберите метку: карточка проекта появляется над картой и открывает историю работы.</p></div>${scene(list,true)}<div class="button-row">${btn('Открыть карту проектов','#/projects-map','clear')}</div><p class="pm-disclosure">Сейчас здесь показан принцип работы карты на демонстрационных материалах. Реальные объекты и их адреса добавляются после согласования публикации.</p></section>`;}
 function page(){const list=projects();return `${crumb([['Портфолио','#/portfolio'],['Карта проектов']])}<section class="selection-page pm-page"><header class="selection-heading"><div class="eyebrow">VIP GLASS / ГЕОГРАФИЯ РАБОТ</div><h1>Истории, которые<br><em>появляются на карте.</em></h1><p>Нажмите на метку — над поверхностью карты появится проект. Откройте его, чтобы посмотреть фотографии и этапы.</p></header><p class="pm-disclosure">Демонстрация интерфейса по вашему референсу. Схема и расположение точек условные; это не адреса выполненных работ.</p><div class="pm-layout">${scene(list)}<aside class="pm-project-list"><h2>Выбрать проект</h2>${list.slice(0,6).map((p,i)=>`<button type="button" data-map-select="${esc(p.id)}" aria-pressed="${i===0}"><img src="${esc(image(p))}" alt="" width="80" height="80"><span><small>${p.isDemo?'Демо · ':''}${String(i+1).padStart(2,'0')}</small><strong>${esc(p.title)}</strong></span><span aria-hidden="true">↗</span></button>`).join('')}<a class="text-button" href="#/portfolio">Все проекты и фильтры ↗</a></aside></div></section>`;}
 function bind(root=globalThis.document){if(!root?.querySelectorAll)return;for(const viewport of root.querySelectorAll('[data-project-map]')){if(viewport.dataset.bound)return;viewport.dataset.bound='1';let zoom=1;const plane=viewport.querySelector('.pm-map-plane'),popover=viewport.querySelector('[data-map-popover]'),scope=viewport.closest('.pm-page,.pm-home')||viewport;const list=projects();const select=id=>{const p=list.find(x=>x.id===id);if(!p)return;for(const pin of scope.querySelectorAll('[data-map-project],[data-map-select]')){const active=(pin.dataset.mapProject||pin.dataset.mapSelect)===id;pin.classList.toggle('is-active',active);pin.setAttribute('aria-pressed',String(active));}const i=list.findIndex(x=>x.id===id),point=points[i]||[50,50];popover.style.left=Math.max(28,Math.min(72,point[0]))+'%';popover.style.top=Math.max(36,Math.min(56,point[1]-6))+'%';popover.innerHTML=popCard(p);popover.classList.remove('pm-reveal');void popover.offsetWidth;popover.classList.add('pm-reveal');};scope.addEventListener('click',e=>{const target=e.target.closest('[data-map-project],[data-map-select]');if(target)select(target.dataset.mapProject||target.dataset.mapSelect);const control=e.target.closest('[data-map-zoom]');if(control){zoom=control.dataset.mapZoom==='reset'?1:Math.max(.8,Math.min(1.8,zoom+(control.dataset.mapZoom==='in'?.2:-.2)));plane.style.setProperty('--map-zoom',zoom);}});}}
 return {page,homepage,bind};
}
